package group

import (
	"bytes"
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/sagernet/sing-box/adapter"
)

// TestAndroidSmartFixtures serializes the production API, not a duplicate JSON schema.
func TestAndroidSmartFixtures(t *testing.T) {
	directory := os.Getenv("SMART_ANDROID_FIXTURES")
	if directory == "" {
		t.Fatal("SMART_ANDROID_FIXTURES must name the Android test resources directory")
	}
	if err := os.MkdirAll(directory, 0o755); err != nil {
		t.Fatal(err)
	}
	write := func(name, data string, err error) {
		t.Helper()
		if err != nil {
			t.Fatal(err)
		}
		var formatted bytes.Buffer
		if err = json.Indent(&formatted, []byte(data), "", "  "); err != nil {
			t.Fatal(err)
		}
		formatted.WriteByte('\n')
		if err = os.WriteFile(filepath.Join(directory, name), formatted.Bytes(), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	s, clock := smartTestGroup()
	ledger, err := getSmartLedger(nil)
	if err != nil {
		t.Fatal(err)
	}
	s.ledger = ledger
	s.installID = "android-fixture-install"
	ledger.Register(s.Tag(), map[string]float64{"wifi": 300, "cellular": 50, "other": 300})
	s.generationSucceeded = true
	s.selectionGeneration = 9
	key := "cell/25001/LTE"
	s.network = smartNetwork{Key: key, Type: "cellular", Label: "Fixture Carrier LTE", Carrier: "Fixture Carrier", Radio: "LTE", Country: "RU", Path: []string{key, "cell/25001", "cell"}, Link: true}
	primary, standby := s.primary, s.standby
	primary.country = "NL"
	primary.rtts = []float64{100, 120, 140}
	primary.udp = smartEvidence{state: "ok", at: clock.now, expires: clock.now.Add(time.Minute)}
	primary.udp443 = smartEvidence{state: "failed", at: clock.now, expires: clock.now.Add(time.Minute)}
	standby.udp443 = smartEvidence{state: "ok", at: clock.now, expires: clock.now.Add(time.Minute)}
	primary.throughput = smartThroughput{Download: 48.1, Upload: 12.5, Source: "active", At: clock.now}
	s.direct = smartEvidence{state: "ok", at: clock.now, expires: clock.now.Add(2 * time.Minute)}
	s.directRTT = 42 * time.Millisecond
	for _, member := range s.members {
		s.history.IdentityServers[member.identity] = member.serverIdentity
	}
	s.history.Observe(s.network.Path, primary.identity, true, 120, clock.now, 0)
	for _, networkKey := range s.network.Path {
		s.history.Networks[networkKey] = &smartHistoryNetwork{Type: "cellular", Label: "Fixture Carrier LTE", Carrier: "Fixture Carrier", Radio: "LTE", LastSeen: clock.now.Unix()}
		stat := s.history.Stats[networkKey][primary.identity]
		stat.Download, stat.Upload, stat.ThroughputAt = 48.1, 12.5, clock.now.Unix()
	}
	s.history.Timeline[key][primary.identity][0].MBPS = 48.1
	to := primary.tag
	s.history.AddEvent(smartEvent{Time: clock.now.Unix(), Kind: "network_change", To: &to, Network: &key, Reason: "fixture generated by core API"})
	manager := smartTestManager{values: []adapter.Outbound{s}}
	status, err := SmartStatus(context.Background(), manager, "")
	write("status.json", status, err)
	networks, err := SmartNetworks(context.Background(), manager, "")
	write("networks.json", networks, err)
	exported, err := SmartExport(context.Background(), manager, false)
	write("export.json", exported, err)

	var document smartExportDocument
	if err = json.Unmarshal([]byte(exported), &document); err != nil {
		t.Fatal(err)
	}
	document.InstallID = "android-fixture-source"
	group := document.Groups[s.Tag()]
	group.Stats = append(group.Stats,
		smartExportStatistic{Network: "wifi/bssid:0123456789abcdef", ServerIdentity: primary.serverIdentity, S: 1, W: 1},
		smartExportStatistic{Network: "other", ServerIdentity: "missing-member", S: 1, W: 1},
	)
	document.Groups[s.Tag()] = group
	incoming, err := smartJSON(document)
	if err != nil {
		t.Fatal(err)
	}
	report, err := SmartImport(context.Background(), manager, incoming, .25)
	write("import-report.json", report, err)
	report, err = SmartImport(context.Background(), manager, incoming, .25)
	write("import-report-replaced.json", report, err)

	empty, _ := smartTestGroup()
	empty.primary, empty.standby = nil, nil
	emptyManager := smartTestManager{values: []adapter.Outbound{empty}}
	status, err = SmartStatus(context.Background(), emptyManager, "")
	write("status-starting.json", status, err)
	networks, err = SmartNetworks(context.Background(), emptyManager, "")
	write("networks-empty.json", networks, err)
	report, err = SmartImport(context.Background(), smartTestManager{}, incoming, .1)
	write("import-report-empty.json", report, err)
}
